const rules = $input.all().map(i => i.json);
const pub = $('Get Publikacja').first().json;

const tresc = (r) => r['Tresc'] || r['Treść'] || '';

const rulesByField = {};
rules.forEach(r => {
  const field = r['Dotyczy Pola'] || 'general';
  if (!rulesByField[field]) rulesByField[field] = [];
  rulesByField[field].push({
    nazwa: r.Nazwa,
    tresc: tresc(r),
    priorytet: r.Priorytet,
    kategoria: r['Kategoria (Dla jakiego typu)']
  });
});

const hashtagiBase = '#dzialki #kolobrzeg #nadmorzem #dzialkirekreacyjne #nieruchomosci';

const systemPrompt = `Jestes copywriterem M&B Investment.

TWARDE REGULY (BAD/GOOD):
- POV firmy 'MY, M&B Investment' (BAD: 'ja, moja dzialka')
- URL zawsze 'https://www.client-site.example' (BAD: 'client-site.example' bez www)
- Brak FAQ w blogach

ZAKAZANE SLOWA (TWARDY ZAKAZ — nigdy, takze w odmianach): "idealny/idealna/idealne", "raj", "okazja zycia", "inwestycja marzen", "kluczowy/kluczowa/kluczowe", "promocja", "unikalna szansa", "wyjatkowa okazja", "ostatnie działki". Pisz RZECZOWO.
BAD: "To idealna inwestycja, kluczowa okazja zycia w raju nad morzem."
GOOD: "Rekreacyjna dzialka nad morzem, rzeczowo i konkretnie."
BAD: "Promocja! Unikalna szansa, wyjatkowa okazja, ostatnie dzialki!"
GOOD: "Dostepna dzialka rekreacyjna, zapytaj o szczegoly."
UWAGA: przyklady BAD i GOOD to wzor TONU, nie wzor tresci. Nie kopiuj z nich lokalizacji, numeru dzialki ani frazy ksiega wieczysta.

Wytyczne SEO klientki (z Airtable):
${Object.entries(rulesByField).map(([field, rs]) =>
  `Dla ${field}:
` + rs.map(r => `- [${r.priorytet}] ${r.nazwa}: ${r.tresc}`).join('
')
).join('

')}

TWARDE REGULY TEKSTOW SOCIAL (FB/IG/TikTok) — MAJA PIERWSZENSTWO PRZED WYTYCZNYMI SEO I FAKTAMI:
1. Pisz NA TEMAT publikacji i obowiazkowo zrealizuj DODATKOWE INSTRUKCJE uzytkownika — to jest os tekstu.
2. Dotyczy publikacji EDUKACYJNYCH/ogolnych. Dla oferty konkretnej dzialki (Typ Rolka Ofertowa) lokalizacja i numer dzialki sa dozwolone takze na poczatku i wtedy tej reguly nie stosuj.
3. W tekstach edukacyjnych NIE zaczynaj od lokalizacji. Zakaz otwierania od [LOCATION], [CITY], nad morzem, numeru dzialki. Pierwsze zdanie ma dotyczyc TEMATU.
4. [LOCATION], [CITY], M&B Investment oraz https://www.client-site.example moga wystapic tylko delikatnie na koncu jako jedna wzmianka lub CTA, nigdy w leadzie.
5. Zakaz off-topic wypelniaczy: nie wprowadzaj watkow ZD vs ROD, pelna wlasnosc, sprawdz MPZP, sprawdz ksiege wieczysta, procedura zakupu, jesli TEMAT ani DODATKOWE INSTRUKCJE wprost tego nie wymagaja.
BAD: W Drzonowie niedaleko [CITY]u dostepne sa dzialki rekreacyjne, dzialka ZD to pelna wlasnosc w odroznieniu od ROD, zawsze sprawdz plan i ksiege wieczysta.
GOOD: Czy to dobry moment na zakup dzialki? Wartosc gruntow rosnie od lat, a dzialka rekreacyjna inaczej niz apartament nie obciaza Cie wysokimi kosztami utrzymania. To spokojna lokata kapitalu. Po wiecej zajrzyj do M&B Investment https://www.client-site.example

Generujesz metadata jako JSON z polami:JEZYK: wszystkie teksty pisz bezbledna, naturalna polszczyzna - poprawna gramatyka, odmiana, skladnia, interpunkcja, polskie znaki; ludzki ton, zero kalk z angielskiego i sztywnych formul AI.
- opis_facebook (700-1200 znakow - czyli 2-3x dluzszy niz dotad: rozwiniety, wartosciowy wpis na kilka akapitow) Z EMOTIKONAMI (4-7 pasujacych emoji wplecionych naturalnie w tekst, nie na sile)
- opis_instagram (100-300 znakow)
- opis_tiktok (max 150 znakow + 3-5 hashtagow w tekscie)
- hashtagi (string) - OBOWIAZKOWO zaczyna sie od base: "${hashtagiBase}" + 3-5 dynamicznych dodatkowych pasujacych do tresci
- blog_tytul (max 60 znakow). KONKRETNA dzialka -> zacznij od lokalizacji. Temat OGOLNY/edukacyjny (Typ publikacji 'Blog Edukacyjny'/'Blog') -> tytul TEMATYCZNY, NIGDY nie prefiksuj lokalizacja ani numerem dzialki. BAD: "[LOCATION] - Media i przylacza na dzialce", "[CITY] dzialka 735: grzyby". Tytul ZBUDUJ ze slow kluczowych TEMATU/Scenariusza tej konkretnej publikacji. NIGDY nie kopiuj zadnego przykladu z tego promptu - to tylko wzor FORMY, nie tresci. Wzor formy: "[glowny temat artykulu] - poradnik"..
- blog_meta_description (max 155 znakow, CTA na koncu). Temat OGOLNY/edukacyjny -> meta TEMATYCZNA, BEZ nazwy/numeru konkretnej dzialki i BEZ prefiksu lokalizacji ([LOCATION]/[CITY]). Region wymieniaj tylko gdy brzmi naturalnie w zdaniu, nie jako etykieta. BAD: "[LOCATION], dzialka 735 - sprawdz media...". GOOD: "Meta ZBUDUJ z TEMATU/Scenariusza tej publikacji. NIGDY nie kopiuj przykladu - to wzor FORMY. Wzor: "[jedno zdanie o tym, czego czytelnik dowie sie z artykulu]. Sprawdz oferte M&B Investment."
- blog_slug (bez polskich znakow). Konkretna dzialka: format dzialka-lokalizacja-numer. Artykul ogolny: format tematyczny ze slow kluczowych tematu (np. warunki-zabudowy-dzialka-rekreacyjna), BEZ numeru/nazwy konkretnej dzialki.`;

return [{
  json: {
    publication_id: pub.id || $('When called by another workflow').first().json.publication_id,
    system_prompt: systemPrompt,
    user_prompt: `TEMAT GLOWNY (najwyzszy priorytet, o tym ma byc tekst):${pub.Blog_Tytul || (pub['Treść Bloga(HTML)']||'').replace(/<[^>]+>/g,'').split('
')[0] || 'zgodnie z trescia ponizej'}
DODATKOWE INSTRUKCJE UZYTKOWNIKA (obowiazkowo zrealizuj w FB/IG/TikTok):${pub['Dodatkowe Info'] || 'brak'}
UWAGA: Scenariusz/Tresc ponizej to material pomocniczy. Czerp z niego TEMAT, ale NIE przenos lokalizacji ([LOCATION]/[CITY]) ani watkow ZD/ROD/plan/KW jesli nie wynikaja z TEMATU lub DODATKOWYCH INSTRUKCJI.

Wygeneruj metadata dla publikacji:

Typ: ${pub['Typ publikacji']}
Scenariusz/Tresc: ${(pub['Wygenerowany scenariusz'] || pub['Treść Bloga(HTML)'] || '').substring(0, 3000)}
 Tytul roboczy: ${pub.Blog_Tytul || ''}

WAZNE:blog_tytul i blog_meta_description zbuduj WYLACZNIE z powyzszego Scenariusza/Tresc(glowny temat tej publikacji). ZAKAZ kopiowania jakichkolwiek przykladow z instrukcji systemowej - to tylko wzory formy.`
  }
}];

const meta = JSON.parse($input.first().json.choices[0].message.content);
const trigger = $('When called by another workflow').first().json;
return [{
  json: {
    publication_id: $('Build Prompt with Rules').first().json.publication_id,
    chat_id: trigger.chat_id || null,
    fields: {
      'Opis_Facebook': meta.opis_facebook,
      'Opis_Instagram': meta.opis_instagram,
      'Opis_TikTok': meta.opis_tiktok,
      'Hashtagi': meta.hashtagi,
      'Blog_Tytul': meta.blog_tytul,
      'Blog_Meta_Description': meta.blog_meta_description,
      'Blog_Slug': meta.blog_slug
    }
  }
}];

// R4-2: deterministyczny strip zakazanych slow (siatka bezpieczenstwa po LLM)
// Dziala na opisy FB/IG/TikTok + tytul/meta bloga. Hashtagi NIE ruszane.
const item = $input.first().json;
const f = item.fields || {};

// kolejnosc: dluzsze/odmiany przed krotszymi (sekwencyjny replace na calym stringu)
const REPLACEMENTS = [
  // idealny/idealna/idealne/... -> dobry/dobra/dobre
  { rx: /idealnego/gi, to: 'dobrego' },
  { rx: /idealnym/gi,  to: 'dobrym' },
  { rx: /idealnej/gi,  to: 'dobrej' },
  { rx: /idealną/gi,   to: 'dobrą' },
  { rx: /idealne/gi,   to: 'dobre' },
  { rx: /idealna/gi,   to: 'dobra' },
  { rx: /idealny/gi,   to: 'dobry' },
  // kluczowy/kluczowa/kluczowe/... -> wazny/wazna/wazne
  { rx: /kluczowego/gi, to: 'ważnego' },
  { rx: /kluczowym/gi,  to: 'ważnym' },
  { rx: /kluczowej/gi,  to: 'ważnej' },
  { rx: /kluczowych/gi, to: 'ważnych' },
  { rx: /kluczową/gi,   to: 'ważną' },
  { rx: /kluczowe/gi,   to: 'ważne' },
  { rx: /kluczowa/gi,   to: 'ważna' },
  { rx: /kluczowy/gi,   to: 'ważny' },
  // frazy marketingowe -> rzeczowo
  { rx: /okazj[aęi] [zż]ycia/gi,        to: 'oferta' },
  { rx: /inwestycj[aię] marze[nń]/gi,   to: 'inwestycja' },
  { rx: /unikaln[aąey]\s+szans[aęy]/gi, to: 'oferta' },
  { rx: /wyj[aą]tkow[aąey]\s+okazj[aęi]/gi, to: 'oferta' },
  { rx: /ostatni[ae]\s+dzia[lł]k[i]/gi, to: 'dostępne działki' },
  { rx: /dzia[lł]k[ai] budowlan[aąey]/gi, to: 'działka rekreacyjna' },
  { rx: /\bpromocj[aęi]\b/gi,           to: 'oferta' },
  { rx: /\braj(u|em)?\b/gi,             to: 'miejsce nad morzem' }
];

function clean(s) {
  if (!s || typeof s !== 'string') return s;
  let out = s;
  for (const { rx, to } of REPLACEMENTS) out = out.replace(rx, to);
  // re-kapitalizacja: poczatek tekstu / po . ! ? / po nowej linii
  out = out.replace(/(^|[.!?]\s+|\n\s*)([a-ząćęłńóśźż])/g, (m, p1, p2) => p1 + p2.toUpperCase());
  out = out.replace(/[ \t]{2,}/g, ' ').trim();
  return out;
}

['Opis_Facebook', 'Opis_Instagram', 'Opis_TikTok', 'Blog_Tytul', 'Blog_Meta_Description']
  .forEach(k => { if (f[k]) f[k] = clean(f[k]); });

item.fields = f;
return [{ json: item }];
